package com.tencent.weknora.storage;
import com.fasterxml.jackson.databind.*;
import java.time.*;
import java.util.stream.*;
import org.junit.jupiter.api.*;
import static org.assertj.core.api.Assertions.*;

/** Fixtures call production Go types/utils/catalog, including actual SQLite-persisted grants. */
class StorageGoCompatibilityTest {
    static final JsonNode oracle;
    static {try(var stream=StorageGoCompatibilityTest.class.getResourceAsStream("/go-storage-cases.json")){oracle=new ObjectMapper().readTree(stream);}catch(Exception ex){throw new ExceptionInInitializerError(ex);}}
    static final String KEY="migration-storage-test-key-32-bytes";
    @TestFactory Stream<DynamicTest> paths(){return StreamSupport.stream(oracle.path("paths").spliterator(),false).map(row->DynamicTest.dynamicTest("Go path: "+row.path("path").asText(),()->{String path=row.path("path").asText();var scope=StoragePaths.scope(path);assertThat(scope.isPresent()).isEqualTo(row.path("scoped").asBoolean());if(scope.isPresent()){assertThat(scope.get().backendId()).isEqualTo(row.path("backend").asText());assertThat(scope.get().path()).isEqualTo(row.path("inner").asText());}assertThat(StoragePaths.provider(path)).isEqualTo(row.path("provider").asText());String handle=StoragePaths.resourceHandle(path);assertThat(handle!=null).isEqualTo(row.path("resource").asBoolean());if(handle!=null)assertThat(handle).isEqualTo(row.path("handle").asText());assertThat(Long.toUnsignedString(FileUrlSigner.tenantFromPath(path))).isEqualTo(row.path("tenant").asText());assertThat(FileUrlSigner.tenantScope(path,1)).isEqualTo(row.path("tenant_scope").asBoolean());assertThat(FileUrlSigner.knowledgeBaseExportScope(path,1)).isEqualTo(row.path("export_scope").asBoolean());}));}
    @TestFactory Stream<DynamicTest> signedURLs(){return StreamSupport.stream(oracle.path("signed").spliterator(),false).map(row->DynamicTest.dynamicTest("Go signature: "+row.path("base").asText()+row.path("path").asText(),()->{long tenant=Long.parseUnsignedLong(row.path("tenant").asText());var signer=new FileUrlSigner(KEY,"",Clock.fixed(Instant.ofEpochSecond(row.path("now").asLong()),ZoneOffset.UTC));assertThat(signer.sign(row.path("base").asText(),row.path("path").asText(),tenant,Duration.ZERO)).isEqualTo(row.path("url").asText());assertThat(signer.verify(row.path("path").asText(),tenant,row.path("expires").asText(),row.path("sig").asText())).isTrue();assertThat(signer.verify(row.path("path").asText()+"x",tenant,row.path("expires").asText(),row.path("sig").asText())).isFalse();}));}
    @TestFactory Stream<DynamicTest> derivedGrants(){return StreamSupport.stream(oracle.path("grants").spliterator(),false).map(row->DynamicTest.dynamicTest("Go persisted grant ttl "+row.path("ttl_nanos").asLong(),()->{var signer=new FileUrlSigner(KEY,"",Clock.fixed(Instant.parse(row.path("now").asText()),ZoneOffset.UTC));var result=signer.derivedGrant(row.path("id").asText(),Duration.ofNanos(row.path("ttl_nanos").asLong())).orElseThrow();assertThat(result.token()).isEqualTo(row.path("token").asText());assertThat(result.expiresAt()).isEqualTo(Instant.parse(row.path("expires").asText()));}));}
    @Test void missingAndExampleKeysNeverSignOrVerify(){for(String key:new String[]{"","short","weknora-system-aes-key-32bytes!!","your-32-byte-long-encryption-key!"}){var signer=new FileUrlSigner(key,"");assertThatThrownBy(()->signer.sign("https://files.test","local://1/a",1,Duration.ZERO)).isInstanceOf(IllegalStateException.class);assertThat(signer.verify("local://1/a",1,"99999999999","anything")).isFalse();assertThat(signer.derivedGrant("id",Duration.ofHours(2))).isEmpty();}}
    @Test void expiryAtBoundaryIsAcceptedAndKeyFallbackIsCompatible(){var now=Instant.ofEpochSecond(123);var signer=new FileUrlSigner("",KEY,Clock.fixed(now,ZoneOffset.UTC));String signature=signer.signature("local://1/a",1,123);assertThat(signer.verify("local://1/a",1,"+123",signature)).isTrue();assertThat(new FileUrlSigner("",KEY,Clock.fixed(now.plusSeconds(1),ZoneOffset.UTC)).verify("local://1/a",1,"123",signature)).isFalse();assertThat(signer.verify("local://1/a",1," 123",signature)).isFalse();}
}
